<template>
  <div class="safe-center-mail">
    <title-line :title="title" />
    <div class="content">
      <div class="box">
        <van-form @submit="onSubmit">
          <div class="title">{{ $t('aqzx.aqzx54') }}</div>
          <van-field
            v-model="olddrawpwd"
            name="原提现密码"
            :type="passwordType"
            label=""
            :placeholder="$t('aqzx.aqzx20')"
            :rules="[{ required: true, message: $t('aqzx.aqzx20') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType">
                <van-icon v-if="passwordType==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx55') }}</div>
          <van-field
            v-model="newdrawpwd"
            style="margin-top:10px"
            :type="passwordType1"
            name="新提现密码"
            label=""
            :placeholder="$t('aqzx.aqzx21')"
            :rules="[{ required: true, message: $t('aqzx.aqzx21') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType1">
                <van-icon v-if="passwordType1==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <div class="title">{{ $t('aqzx.aqzx55') }}</div>
          <van-field
            v-model="confirmpwd"
            style="margin-top:10px"
            :type="passwordType2"
            name="确认新提现密码"
            label=""
            :placeholder=" $t('aqzx.aqzx22')"
            :rules="[{ required: true, message: $t('aqzx.aqzx22') }]"
          >
            <template slot="right-icon">
              <span class="soltseye" @click="switchPasswordType2">
                <van-icon v-if="passwordType2==='password'" name="eye" />
                <van-icon v-else name="closed-eye" />
              </span>
            </template>
          </van-field>
          <!-- <div class="tips" style="margin:20px 0 30px 0">
            <div class="warning_icon" />
            <span>为了保障您的账号和资金安全，请绑定邮箱</span>
          </div> -->
          <div style="margin: 40px auto 10px 0;">
            <van-button
              class="btn-bg"
              block
              type="info"
              native-type="submit"
            >{{ $t('aqzx.aqzx23') }}</van-button>
          </div>
          <div class="forgetPsd"><span @click="goMore">{{ $t('aqzx.aqzx24') }}</span></div>
        </van-form>
      </div>
    </div>

  </div>
</template>
<script>
import TitleLine from './modules/TitleLine'
import { editdrawpwd } from '@/api/safe'
export default {
  components: {
    TitleLine
  },
  props: {
  },
  data() {
    return {
      title: this.$t('aqzx.aqzx07'),
      olddrawpwd: '',
      newdrawpwd: '',
      confirmpwd: '',
      passwordType: 'password',
      passwordType1: 'password',
      passwordType2: 'password'
    }
  },
  methods: {
    switchPasswordType() {
      this.passwordType = this.passwordType === 'password' ? 'text' : 'password'
    },
    switchPasswordType1() {
      this.passwordType1 = this.passwordType1 === 'password' ? 'text' : 'password'
    },
    switchPasswordType2() {
      this.passwordType2 = this.passwordType2 === 'password' ? 'text' : 'password'
    },
    goMore() {
      this.$router.push({ path: '/forgetDrawpwd' })
    },
    onSubmit() {
      if (this.newdrawpwd !== this.confirmpwd) {
        this.$toast('两次输入的密码不一致')
        return false
      }
      editdrawpwd({ olddrawpwd: this.olddrawpwd, newdrawpwd: this.newdrawpwd }).then(res => {
        if (res.status === '1') {
          this.$toast('设置成功')
          setTimeout(() => {
            this.$router.push({ path: '/safeCenter' })
          }, 2000)
        }
      })
    }
  }

}
</script>
<style lang="scss" scoped>
.safe-center-mail {
    min-height: 100vh;
    width: 100%;
    background: var(--inner-bg-color);
    background-position: 0% 0%;
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
  .van-field__right-icon{
    margin-right: 20px;
    color: rgb(67, 83, 125);
  }
    .containers{
    position: relative;
    padding: 0px 30px 0px;
    }
    .content{
        margin: auto 28px;
        .box {
          margin-top: 36px;
          padding: 40px;
          border-radius: 28px;
          background: rgba(241, 229, 255,0.12);
          border-radius: 8px;
        .title {
            margin-bottom: 16px;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: rgba(255, 255, 255,0.75);
            letter-spacing: 0;
            line-height: 40px;
            font-weight: 400;
        }
        .title:not(:first-child){
          margin-top: 40px;
        }
        .tips {
            color: #fff;
            position: relative;
            .warning_icon {
                position: absolute;
                top: 6px;
                width: 20px;
                height: 20px;
                background-image: url(~@/assets/portal/warning_icon.png);
                background-position: 0% 0%;
                background-size: 100% 100%;
                background-repeat: no-repeat;
            }
            span {
                margin-left: 28px;
            }
        }
        .forgetPsd{
            text-align: center;
            font-family: PingFangSC-Regular;
            font-size: 28px;
            color: #00B7FF;
            font-weight: 400;
        }
     }
    }

}
</style>
